"import re, subprocess, sys, json

html = open("/private/tmp/pcd-sbx-gemini-4-hydrogen-xhigh-r2-6hxpld1f/work/index.html", "r", encoding="utf-8").read()

m_strat = re.search(r'<script id="rampart-strategy">([\s\S]*?)</script>', html)
m_sim = re.search(r'<script id="rampart-sim">([\s\S]*?)</script>', html)
assert m_strat and m_sim, "Missing required script blocks"

strat_code = m_strat.group(1)
sim_code = m_sim.group(1)

# 1. Check forbidden identifiers in strategy and sim
for bad in ["window", "document", "THREE", "Math.random", "Date", "performance"]:
    assert bad not in strat_code, f"Forbidden token '{bad}' in rampart-strategy"
for bad in ["window", "document", "THREE", "AudioContext", "webkitAudioContext"]:
    assert bad not in sim_code, f"Forbidden token '{bad}' in rampart-sim"

# 2. Check external script tags
scripts = re.findall(r'<script[^>]*src=[^>]*>', html)
assert scripts == ['<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>'], f"Unexpected external scripts: {scripts}"

# 3. Check no fetch/XHR/WebSocket/importmap
for bad in ["importmap", "fetch(", "XMLHttpRequest", "WebSocket", "TextureLoader"]:
    assert bad not in html, f"Forbidden pattern '{bad}' in index.html"

# 4. Run extracted scripts in clean jsc
